with open('semver.py', 'r') as f:
    content = f.read()

# Let's identify exact line ranges for modifications
lines = content.split('\n')
for i, line in enumerate(lines):
    if 'class VersionInfo' in line:
        print(f"VersionInfo class starts at line {i+1}")
    elif '__slots__' in line:
        print(f"__slots__ at line {i+1}: {line}")
    elif 'def __eq__' in line:
        print(f"__eq__ at line {i+1}")
    elif 'def __ne__' in line:
        print(f"__ne__ at line {i+1}")
    elif 'def __lt__' in line:
        print(f"__lt__ at line {i+1}")
    elif 'def __le__' in line:
        print(f"__le__ at line {i+1}")
    elif 'def __gt__' in line:
        print(f"__gt__ at line {i+1}")
    elif 'def __ge__' in line:
        print(f"__ge__ at line {i+1}")
    elif 'def __hash__' in line:
        print(f"__hash__ at line {i+1}")
    elif 'def parse(self)' in line or 'def parse(' in line:
        print(f"parse at line {i+1}: {line[:50]}")
